-- =======================================================================
-- V300154：按 FinvQuantDesign/Mapping/finv_futu_query_stat-2.json 补录 finv_security 初始数据（需求 11070）
--
-- 来源：FinvQuantDesign/Mapping/finv_futu_query_stat-2.json（489 行，取自富途采集属性表结构：
--   usc / stock_id / futu_symbol / ftmm_symbol / market_label / market_type / market_code /
--   instrument_type / sub_instrument_type / instrument；**不含证券名称与币种**）
--   名称/英文名改由上游 public.finv_quote_secu_meta 补齐（按 usc 命中 84 行，其余按 ftmm_symbol 再匹配，共 480 行有名称）。
--
-- 现状（迁移前实测）：489 个 usc 中 210 个已在 public.finv_security；
--   剩余 279 个里 11 个已存在但写法不同（大小写不一致）——同步跳过，不重复登记：
--     HK 指数 800000→HSI、800700→HSTI；HK 期货主连/当月等 9 条（CNCMain / GDRCurrent / GDRMain /
--     GDRNext / GDUMain / HSIMain / HTIMain / METMain / MIUMain，来源里写作 xxMain / xxmain）。
--   本迁移实际补录 268 行。
--
-- 字段口径（对齐库里既有行的主导写法）：
--   exchange_code：HK 21 / SZ 12（其余市场本批未出现）；
--   market_code（finv 侧）：HK 股票/ETF 1201（08xxxx 为 1202）、HK 期货 1250、SZ 1120（30xxxx 1121）；
--   security_type：instrument_type 3→Stock、4→ETF、6→StockIndex、9→Futures、12→Stock；
--   type_secu_sub：Stock/ETF/StockIndex 取 `{security_type}.{market_label}`，Futures 留空；
--   security_code = 来源 futu_symbol；security_name(_full) = 上游 name_en（缺则 name）；
--   security_name_cn = 上游 name；currency_type：HK HKD、SZ/SH/BJ CNY、US USD（来源无币种列，按市场定）；
--   init_date 20000000、provider 'FTMM'、flag_enable '1'、remark 'finv_futu_query_stat-2' 标来源；
--   timezone/tz：HK 期货 +08:00 / Asia/Hong_Kong，其余 +08:00 / Asia/Shanghai。
--
-- 幂等：INSERT ... ON CONFLICT DO NOTHING（主键 usc、唯一 (exchange_code, security_code)）。
-- 迁移策略：单事务；末尾校验来源标记行数。
-- =======================================================================

BEGIN;

-- ---- public.finv_security：268 行 ----

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;
DO $$
DECLARE
    v bigint;
BEGIN
    SELECT count(*) INTO v FROM public.finv_security WHERE remark = 'finv_futu_query_stat-2';
    IF v <> 268 THEN
        RAISE EXCEPTION 'V300154 校验失败：应有 268 行来源标记数据，实际 % 行', v;
    END IF;
    RAISE NOTICE 'V300154：public.finv_security 补 268 行（另 11 行大小写不一致的既有登记跳过）';
END $$;

COMMIT;
